# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAVZA GENELGESİ (28 MAYIS 1919) — MİLLÎ BİLİNCİN UYANDIRILMASI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Havza Genelgesi\'nin Maddeleri</text>\n  <text x="40" y="100" font-size="11.5" fill="#334155">• İşgallere karşı <tspan font-weight="bold" fill="#1e3a8a">protesto mitingleri</tspan></text>\n  <text x="48" y="117" font-size="11.5" fill="#334155">düzenlenmeli ve millî heyecan gösterilmelidir.</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• İtilaf Devletleri ve İstanbul Hükümeti\'ne</text>\n  <text x="48" y="159" font-size="11.5" fill="#334155"><tspan font-weight="bold" fill="#1e3a8a">kınama telgrafları</tspan> çekilmelidir.</text>\n  <text x="40" y="184" font-size="11.5" fill="#334155">• Mitinglerde Hristiyan azınlıklara</text>\n  <text x="48" y="201" font-size="11.5" font-weight="bold" fill="#b91c1c">kesinlikle kötü muamele edilmemelidir.</text>\n  <text x="40" y="224" font-size="11.5" fill="#334155">• Ordular dağıtılmamalı, silahlar teslim edilmemelidir.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="73" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Tarihsel Önemi ve Yorumu</text>\n  <text x="375" y="100" font-size="11.5" fill="#334155">✓ Mustafa Kemal Paşa\'nın 9. Ordu Müfettişi</text>\n  <text x="387" y="117" font-size="11.5" fill="#334155">yetkisiyle <tspan font-weight="bold">tek başına</tspan> yayımladığı genelgedir.</text>\n  <text x="375" y="144" font-size="11.5" fill="#334155">✓ Türk halkında işgallere karşı <tspan font-weight="bold" fill="#14532d">millî bilincin</tspan></text>\n  <text x="387" y="161" font-size="11.5" fill="#334155"><tspan font-weight="bold" fill="#14532d">(ulusal farkındalığın) uyanmasını</tspan> sağlamıştır.</text>\n  <text x="375" y="188" font-size="11.5" fill="#334155">✓ Azınlıklara kötü davranılmaması uyarısıyla</text>\n  <text x="387" y="205" font-size="11.5" fill="#334155"><tspan font-weight="bold">Mondros\'un 7. maddesine</tspan> dayalı yeni işgallerin</text>\n  <text x="387" y="222" font-size="11.5" fill="#334155">haklı gösterilmesi (bahane üretilmesi) önlenmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AMASYA GENELGESİ (22 HAZİRAN 1919) — AMAÇ, GEREKÇE VE YÖNTEM</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">1. GEREKÇE (Neden?)</text>\n  <text x="32" y="96" font-size="10.5" fill="#334155">• "Vatanın bütünlüğü, milletin</text>\n  <text x="40" y="112" font-size="10.5" fill="#334155">bağımsızlığı tehlikededir."</text>\n  <text x="32" y="136" font-size="10.5" fill="#334155">• "İstanbul Hükümeti üzerine</text>\n  <text x="40" y="152" font-size="10.5" fill="#334155">aldığı sorumluluğun gereğini</text>\n  <text x="40" y="168" font-size="10.5" fill="#334155">yerine getirememektedir."</text>\n  <text x="32" y="196" font-size="10.5" font-weight="bold" fill="#854d0e">→ Millî Mücadele\'nin iki temel</text>\n  <text x="40" y="212" font-size="10.5" font-weight="bold" fill="#854d0e">gerekçesi açıklanmıştır.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">2. AMAÇ VE YÖNTEM</text>\n  <text x="257" y="98" font-size="10.5" font-weight="bold" fill="#1e3a8a">"Milletin bağımsızlığını,</text>\n  <text x="257" y="114" font-size="10.5" font-weight="bold" fill="#1e3a8a">yine milletin azim ve kararı</text>\n  <text x="257" y="130" font-size="10.5" font-weight="bold" fill="#1e3a8a">kurtaracaktır."</text>\n  <text x="257" y="156" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Amaç:</tspan> Milletin bağımsızlığı</text>\n  <text x="257" y="176" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Yöntem:</tspan> Milletin azim ve kararı</text>\n  <text x="257" y="198" font-size="10.5" font-weight="bold" fill="#15803d">• İlk kez Millî Egemenlik</text>\n  <text x="265" y="214" font-size="10.5" fill="#15803d">(İhtilal Bildirgesi niteliği)</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">3. KURUMSALLAŞMA</text>\n  <text x="482" y="96" font-size="10.5" fill="#334155">• Her türlü etki ve denetimden</text>\n  <text x="490" y="112" font-size="10.5" fill="#334155">uzak <tspan font-weight="bold">millî bir kurul</tspan> (Temsil</text>\n  <text x="490" y="128" font-size="10.5" fill="#334155">Heyeti) fikri ilk kez ortaya atıldı.</text>\n  <text x="482" y="154" font-size="10.5" fill="#334155">• <tspan font-weight="bold">Sivas\'ta</tspan> ulusal bir kongre</text>\n  <text x="490" y="170" font-size="10.5" fill="#334155">toplanması kararlaştırıldı.</text>\n  <text x="482" y="196" font-size="10.5" font-weight="bold" fill="#9d174d">• Çok imzalı yayımlandı:</text>\n  <text x="490" y="212" font-size="10" fill="#475569">Kişisellikten çıkarıp halka mal etme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ERZURUM KONGRESİ (23 TEMMUZ - 7 AĞUSTOS 1919)</text>\n  <rect x="25" y="48" width="650" height="44" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="75" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Toplanış amacı ve şekli bakımından BÖLGESEL; aldığı kararlar bakımından MİLLÎ (ULUSAL) bir kongredir!</text>\n  <rect x="25" y="102" width="315" height="138" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Bağımsızlık ve Vatan Bütünlüğü Kararları</text>\n  <text x="38" y="148" font-size="11" fill="#334155">• <tspan font-weight="bold">"Millî sınırlar içinde vatan bir bütündür, bölünemez."</tspan></text>\n  <text x="46" y="164" font-size="10.5" fill="#1e3a8a">→ İlk kez millî sınırlardan (Misakımillî) bahsedildi.</text>\n  <text x="38" y="186" font-size="11" fill="#334155">• <tspan font-weight="bold">"Manda ve himaye kabul olunamaz."</tspan></text>\n  <text x="46" y="202" font-size="10.5" fill="#1e3a8a">→ İlk kez manda reddedildi; tam bağımsızlık seçildi.</text>\n  <text x="38" y="224" font-size="11" fill="#334155">• Azınlıklara siyasi dengeyi bozacak ayrıcalık verilemez.</text>\n  <rect x="360" y="102" width="315" height="138" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="124" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Millî Egemenlik ve Temsil Kararları</text>\n  <text x="373" y="148" font-size="11" fill="#334155">• <tspan font-weight="bold">"Kuvâ-yı Millîye\'yi etkin, millî iradeyi hâkim kılmak esastır."</tspan></text>\n  <text x="381" y="164" font-size="10.5" fill="#14532d">→ Ulusal egemenliğe dayalı yeni rejim mesajı verildi.</text>\n  <text x="373" y="186" font-size="11" fill="#334155">• <tspan font-weight="bold">"Mebusan Meclisi derhal toplanmalı ve hükümet</tspan></text>\n  <text x="381" y="202" font-size="11" font-weight="bold" fill="#334155">işleri meclis denetiminde yürütülmelidir."</text>\n  <text x="373" y="224" font-size="11" fill="#334155">• 9 kişilik <tspan font-weight="bold" fill="#14532d">Temsil Heyeti</tspan> kuruldu (Başkanı: Mustafa Kemal).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
